package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

var WsEofFlag string         // PIC X len=1 = "N"
var WsBal decimal.Decimal    // PIC 9(8)V99 len=10 = 0
var WsYear int64             // PIC 99 len=2 = 0
var WsCount int64            // PIC 99 len=2 = 0
var WsBalEd string            // PIC ZZ,ZZZ,ZZ9.99 len=13

var schedRec SchedRec

var schedFile *os.File
var schedScanner *bufio.Scanner
var schedEOF bool

func formatPIC9(val int64, width int) string {
	// keep low-order digits
	if width <= 0 {
		return ""
	}
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	// handle negative: COBOL would keep sign? not needed here
	if val < 0 {
		val = -val
		val = val % mod
		// for negative we would need sign handling; not required
		return fmt.Sprintf("%0*d", width, val)
	}
	val = val % mod
	return fmt.Sprintf("%0*d", width, val)
}

func formatPICZZZZZZZZ9_99(v decimal.Decimal) string {
	picture := "ZZ,ZZZ,ZZ9.99"
	// scale = number of 9/Z after dot
	dotIdx := strings.Index(picture, ".")
	nFrac := 0
	nIntPlaceholders := 0
	for i, ch := range picture {
		if ch == 'Z' || ch == '9' {
			if dotIdx >= 0 && i > dotIdx {
				nFrac++
			} else if dotIdx < 0 || i < dotIdx {
				// before dot
				nIntPlaceholders++
			}
		}
	}
	// Ensure v is at scale nFrac (it should be)
	// Get string fixed with nFrac digits
	neg := v.IsNegative()
	absV := v.Abs()
	s := absV.StringFixed(int32(nFrac)) // e.g. "1000.00"
	intStr := ""
	fracStr := ""
	if nFrac > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		}
		// pad frac to nFrac
		if len(fracStr) < nFrac {
			fracStr = fracStr + strings.Repeat("0", nFrac-len(fracStr))
		} else if len(fracStr) > nFrac {
			fracStr = fracStr[:nFrac]
		}
	} else {
		intStr = s
	}
	// keep low-order integer digits if overflow
	if len(intStr) > nIntPlaceholders {
		intStr = intStr[len(intStr)-nIntPlaceholders:]
	} else if len(intStr) < nIntPlaceholders {
		intStr = strings.Repeat("0", nIntPlaceholders-len(intStr)) + intStr
	}
	// Now build output array
	out := []rune(picture)
	// Map integer placeholder positions
	intPos := []int{}
	for i, ch := range picture {
		if ch == 'Z' || ch == '9' {
			if dotIdx >= 0 && i < dotIdx {
				intPos = append(intPos, i)
			} else if dotIdx < 0 {
				intPos = append(intPos, i)
			}
		}
	}
	fracPos := []int{}
	if dotIdx >= 0 {
		for i, ch := range picture {
			if (ch == 'Z' || ch == '9') && i > dotIdx {
				fracPos = append(fracPos, i)
			}
		}
	}
	// fill integer digits
	for idx, pos := range intPos {
		out[pos] = rune(intStr[idx])
	}
	// fill fractional digits
	for idx, pos := range fracPos {
		if idx < len(fracStr) {
			out[pos] = rune(fracStr[idx])
		} else {
			out[pos] = '0'
		}
	}
	// Z suppression for integer part
	// Find left to right suppression: Z's with leading zero
	suppressed := true
	for _, pos := range intPos {
		pch := rune(picture[pos])
		if pch == 'Z' && suppressed && out[pos] == '0' {
			out[pos] = ' '
		} else {
			// this position is not suppressed (either '9' or non-zero Z)
			// but need to check: if pch == '9' we always show, and suppression ends
			// if pch == 'Z' and digit != '0', suppression ends
			suppressed = false
		}
		if !suppressed {
			// once suppression ended, remaining Z's show digits as is
			// no further action
		}
	}
	// commas inside suppressed zone become spaces
	// A comma is suppressed if all integer placeholders to its left are suppressed (i.e., are spaces)
	// We can determine: for each comma position before dot, check if every int placeholder left of it is space
	for i, ch := range picture {
		if ch == ',' {
			// find int placeholders left of i
			allSpace := true
			hasLeft := false
			for _, p := range intPos {
				if p < i {
					hasLeft = true
					if out[p] != ' ' {
						allSpace = false
						break
					}
				}
			}
			if hasLeft && allSpace {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
		if ch == '.' {
			out[i] = '.'
		}
	}
	_ = neg
	return string(out)
}

func storePIC9V99(val decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var v decimal.Decimal
	if rounded {
		v = val.Round(scale)
	} else {
		v = val.Truncate(scale)
	}
	// apply overflow: keep low-order digits
	// scaled = v * 10^scale
	scaled := v.Shift(scale) // decimal
	// divisor = 10^(intDigits+scale)
	exp := int32(intDigits) + scale
	divisor := decimal.New(1, exp)
	// for positive, modulo; for negative, need to keep sign? Simplified: work with absolute and restore sign
	if scaled.IsNegative() {
		absScaled := scaled.Abs()
		mod := absScaled.Mod(divisor)
		v2 := mod.Shift(-scale)
		v2 = v2.Neg()
		return v2
	}
	mod := scaled.Mod(divisor)
	return mod.Shift(-scale)
}

func parsePIC9V99(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, 0)
	}
	// keep only digits, ignore other chars?
	// s should be digits
	// Remove any non-digit (should not happen)
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.New(0, 0)
	}
	// parse as integer
	d, err := decimal.NewFromString(digits)
	if err != nil {
		// fallback
		var n int64
		fmt.Sscanf(digits, "%d", &n)
		d = decimal.New(n, 0)
	}
	return d.Shift(-scale)
}

func parsePIC9(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return 0
	}
	var n int64
	fmt.Sscanf(digits, "%d", &n)
	return n
}

func inputDone() bool {
	return WsEofFlag == "Y"
}

func MAIN_PARA() {
	// OPEN INPUT SCHED-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		WsEofFlag = "Y"
		schedEOF = true
	} else {
		schedFile = f
		schedScanner = bufio.NewScanner(f)
	}
	READ_PARA()
	for !inputDone() {
		PROCESS_PARA()
	}
	if schedFile != nil {
		schedFile.Close()
	}
	// DISPLAY "SCHEDULES: " WS-COUNT
	// WS-COUNT is PIC 99 zero-padded width 2
	cntStr := formatPIC9(WsCount, 2)
	fmt.Printf("SCHEDULES: %s\n", cntStr)
}

func READ_PARA() {
	if schedScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if schedScanner.Scan() {
		line := schedScanner.Text()
		// pad with spaces to record length 16
		if len(line) < 16 {
			line = line + strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		// parse fields
		rawAcct := line[0:4]
		rawPrin := line[4:11]
		rawRate := line[11:15]
		rawYears := line[15:16]
		schedRec.ScAcct = rawAcct
		schedRec.ScPrin = parsePIC9V99(rawPrin, 2)
		schedRec.ScRate = parsePIC9V99(rawRate, 2)
		schedRec.ScYears = parsePIC9(rawYears)
		WsEofFlag = "N"
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = storePIC9V99(schedRec.ScPrin, 8, 2, false)
	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	WsYear = 1
	for !(WsYear > schedRec.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		one := decimal.NewFromInt(1)
		hundred := decimal.NewFromInt(100)
		rateDiv := schedRec.ScRate.Div(hundred) // use Div for this division; alternative Shift but rate has scale 2
		// To avoid Div precision issues, we can do rate.Shift(-2)
		// Use Shift for exactness:
		rateDiv = schedRec.ScRate.Shift(-2)
		factor := one.Add(rateDiv)
		computed := WsBal.Mul(factor)
		WsBal = storePIC9V99(computed, 8, 2, true)
		WsBalEd = formatPICZZZZZZZZ9_99(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		yearStr := formatPIC9(WsYear, 2)
		fmt.Printf("%s Y%s %s\n", schedRec.ScAcct, yearStr, WsBalEd)
		WsYear++
	}
	WsBalEd = formatPICZZZZZZZZ9_99(WsBal)
	fmt.Printf("%s FINAL %s\n", schedRec.ScAcct, WsBalEd)
	WsCount++
	// ADD 1 TO WS-COUNT with overflow handling (PIC 99)
	WsCount = WsCount % 100
	READ_PARA()
}

func main() {
	WsEofFlag = "N"
	WsBal = decimal.New(0, 0)
	WsYear = 0
	WsCount = 0
	WsBalEd = ""
	MAIN_PARA()
}
